function hashSeed(seed: string): number {
  let h = 0;
  for (let i = 0; i < seed.length; i++) h = (h * 31 + seed.charCodeAt(i)) >>> 0;
  return h;
}

export function fallbackCoverUrl(article: Pick<ArticleSummary, "title" | "category" | "slug">) {
  const cat = (article.category || "news").toLowerCase();
  const pool = CATEGORY_IMAGE_POOLS[cat] || CATEGORY_IMAGE_POOLS.world;
  const idx = hashSeed(article.slug || article.title || "") % pool.length;
  return pool[idx];
}
